import type { CountryId, CountryInfo } from "@gs/shared";
import raw from "./countries.json";

/** Reference facts for every map region, keyed by id. Generated by scripts/build-countries.mjs. */
export const COUNTRIES = raw as unknown as Record<CountryId, CountryInfo>;
export const COUNTRY_LIST: CountryInfo[] = Object.values(COUNTRIES).sort((a, b) => a.name.localeCompare(b.name));

export function getCountry(id: CountryId | null | undefined): CountryInfo | undefined {
  return id ? COUNTRIES[id] : undefined;
}

export function flagUrl(c: CountryInfo): string | null {
  return c.hasFlag ? `${import.meta.env.BASE_URL}flags/${c.id}.svg` : null;
}

/** Search by common or official name. Names that start with the query rank first. */
export function searchCountries(query: string, limit = 8): CountryInfo[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const scored: [number, CountryInfo][] = [];
  for (const c of COUNTRY_LIST) {
    const name = c.name.toLowerCase();
    const official = (c.officialName ?? "").toLowerCase();
    let score = -1;
    if (name.startsWith(q)) score = 0;
    else if (name.split(/[\s-]/).some((w) => w.startsWith(q))) score = 1;
    else if (name.includes(q) || official.includes(q) || c.id.toLowerCase() === q) score = 2;
    if (score >= 0) scored.push([score, c]);
  }
  return scored.sort((a, b) => a[0] - b[0] || a[1].name.localeCompare(b[1].name)).slice(0, limit).map(([, c]) => c);
}
